import { useId } from 'react';
import { TokenSearchField } from '@kerfjs/ui/token-search-field';
import '@kerfjs/ui/layout.css';

export type FilterToken = {id:string; label:string; value:string};
export type SearchValue = {text:string; tokens:FilterToken[]};
export type Caret = {start:number; end:number};
export type Suggestion = {id:string; label:string; token:FilterToken; replaceTokenId?:string};
type Props = {
  value: SearchValue;
  caret: Caret;
  suggestions: Suggestion[];
  onChange: (value: SearchValue, caret: Caret) => void;
  parse: (text: string, tokens: FilterToken[], caret: Caret) => {value:SearchValue; caret:Caret};
  onSubmit: (value:SearchValue) => void;
};
export function WorkspaceSearch({value, caret, suggestions, onChange, parse, onSubmit}:Props) {
  const hint = useId();
  const commitSuggestion = (suggestion:Suggestion) => {
    const index = suggestion.replaceTokenId ? value.tokens.findIndex(token => token.id === suggestion.replaceTokenId) : -1;
    const tokens = [...value.tokens];
    if (index >= 0) tokens.splice(index, 1, suggestion.token);
    else tokens.push(suggestion.token);
    onChange({text:value.text, tokens}, caret);
  };
  return <div className="kui-layout">
    <TokenSearchField
      aria-label="Search workspace and filters"
      aria-describedby={hint}
      value={value}
      selection={caret}
      suggestions={suggestions}
      onValueChange={(next:SearchValue, nextCaret:Caret) => {
        const parsed = parse(next.text, next.tokens, nextCaret);
        onChange(parsed.value, parsed.caret);
      }}
      onSelectionChange={(nextCaret:Caret) => onChange(value, nextCaret)}
      onTokenRemove={(id:string) => onChange({...value, tokens:value.tokens.filter(token => token.id !== id)}, caret)}
      onTokenReplace={(id:string, replacement:FilterToken) => onChange({...value, tokens:value.tokens.map(token => token.id === id ? replacement : token)}, caret)}
      onSuggestionSelect={commitSuggestion}
      onClear={() => onChange({text:'', tokens:[]}, {start:0, end:0})}
      onSubmit={() => onSubmit(value)}
    />
    <p id={hint}>Type to search. Use the keyboard to choose suggestions or edit and remove filters.</p>
  </div>;
}
// The application owns ordered tokens, parsing, suggestions, and the selection
// snapshot. TokenSearchField owns its single editor, token keyboard behavior,
// named removal controls, and restoring the controlled caret after edits.
// No second input or parallel chip editor is created.
